import { recoverySession } from '@/lib/recovery-session';
import { createAuthFetch } from '@/lib/auth-fetch';
import { applicationAuthStorageKey } from '@/lib/app-auth';
// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  global: { fetch: createAuthFetch(SUPABASE_URL) },
  auth: {
    storage: localStorage,
    storageKey: applicationAuthStorageKey(SUPABASE_URL, window.location.pathname),
    persistSession: true,
    autoRefreshToken: true,
  }
});
// Register before React mounts: initialization may consume the callback first.
supabase.auth.onAuthStateChange((event, session) => {
  if (event === "PASSWORD_RECOVERY") recoverySession.begin(session);
  else if (event === "SIGNED_OUT") recoverySession.clear();
});
